package com.jadhavr.erp.account.dto; import com.jadhavr.erp.user.entity.UserStatus; import jakarta.validation.constraints.*; import java.time.LocalDateTime; import java.util.Set; public final class AccountDtos{private AccountDtos(){} public record UpdateProfile(@NotBlank @Size(min=2,max=150)String fullName,@Size(max=20)String phone){} public record ChangePassword(@NotBlank String currentPassword,@NotBlank @Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9]).{8,72}$",message="Password must contain upper, lower, number and special character")String newPassword,@NotBlank String confirmPassword){} public record Profile(Long id,Long collegeId,String collegeName,String collegeCode,String fullName,String email,String phone,UserStatus status,Set<String>roles,LocalDateTime lastLoginAt,LocalDateTime createdAt,LocalDateTime updatedAt){} }
